private final EncryptionUtils.EncryptResult encryptRequestBody(Request request) {
    RequestBody requestBodyBody = request.body();
    if (requestBodyBody == null) {
        return null;
    }
    try {
        Buffer buffer = new Buffer();
        requestBodyBody.writeTo(buffer);
        String utf8 = buffer.readUtf8();
        if (StringsKt.isBlank(utf8)) {
            return null;
        }
        String strEncodedPath = request.url().encodedPath();
        LogUtil.INSTANCE.d(TAG, ">>> Encrypting request [" + request.method() + "] " + strEncodedPath);
        try {
            return EncryptionUtils.encrypt$default(EncryptionUtils.INSTANCE, strEncodedPath, parseJsonToMap(utf8), null, null, 12, null);
        } catch (Exception e) {
            LogUtil.INSTANCE.e(TAG, "Encryption failed for " + strEncodedPath + ": " + e.getMessage());
            return null;
        }
    } catch (Exception e2) {
        LogUtil.INSTANCE.e(TAG, "Failed to read request body: " + e2.getMessage());
        return null;
    }
}
